    if (remove != null) {
        player.getAttributes().removeModifiers(remove.getAttributeModifiers(MAINHAND));
    }
    if (add != null) {
        player.getAttributes().addTemporaryModifiers(add.getAttributeModifiers(MAINHAND));
    }
}

