public void tick(World world) {
	for (D key : new HashSet<>(eventQueue.keySet())) {
		Integer tickCounter = eventQueue.get(key);
		if (tickCounter >= 1) {
			eventQueue.put(key, tickCounter - 1);
		} else {
			this.callback.triggerEvent(world, this, key);
			eventQueue.remove(key);
		}
	}
}

