	this.setOwner(owner);
	this.setPosition(owner.getX() - (owner.getWidth() + 1.0F) * 0.5 * MathHelper.sin(owner.bodyYaw * 0.017453292F), owner.getEyeY() - 0.1, owner.getZ() + (owner.getWidth() + 1.0F) * 0.5 * (double) MathHelper.cos(owner.bodyYaw * 0.017453292F));
}

